public void testUpdateOrAppend() throws Exception {
    final Preference preference = createPreference(_testId, "test", "X-query", Collections.<String, Object>singletonMap("select", "id,name"));
    Subject.doAs(_subject, new PrivilegedAction<Void>() {

        @Override
        public Void run() {
            awaitPreferenceFuture(_userPreferences.updateOrAppend(Collections.singleton(preference)));
            return null;
        }
    });
    verify(_preferenceStore).updateOrCreate(argThat(new PreferenceRecordMatcher(preference)));
}

public void testReplace() throws Exception {
    final Preference preference = createPreference(_testId, "test", "X-query", Collections.<String, Object>singletonMap("select", "id,name"));
    Subject.doAs(_subject, new PrivilegedAction<Void>() {

        @Override
        public Void run() {
            awaitPreferenceFuture(_userPreferences.replace(Collections.singleton(preference)));
            return null;
        }
    });
    verify(_preferenceStore).replace(argThat(new UUIDCollectionMatcher(Collections.<UUID>emptyList())), argThat(new PreferenceRecordMatcher(preference)));
}

public void testReplaceByType() throws Exception {
    final UUID queryUUID = UUID.randomUUID();
    final Preference queryPreference = createPreference(queryUUID, "test", "X-query", Collections.<String, Object>emptyMap());
