    Map<String, Object> queueAttributes = new HashMap<>();
    queueAttributes.put(Queue.NAME, getName());
    queueAttributes.putAll(attributes);
    verify(_handler).handle(matchesRecord(_queueId, QUEUE, queueAttributes));
}

