    assertNotNull("Trust store 2 is not found after upgrade", trustStore2Upgraded);
    assertNotNull("Trust store 3 is not found after upgrade", trustStore3Upgraded);
    assertEquals("Unexpected attributes after upgrade for Trust store 1", trustStoreAttributes1, new HashMap<>(trustStore1Upgraded.getAttributes()));
    assertEquals("includedVirtualHostNodeMessageSources is not found", "true", trustStore2Upgraded.getAttributes().get("includedVirtualHostNodeMessageSources"));
    assertNull("includedVirtualHostMessageSources is  found", trustStore2Upgraded.getAttributes().get("includedVirtualHostMessageSources"));
    assertEquals("includedVirtualHostNodeMessageSources is not found", "true", trustStore3Upgraded.getAttributes().get("excludedVirtualHostNodeMessageSources"));
    assertNull("includedVirtualHostMessageSources is  found", trustStore3Upgraded.getAttributes().get("excludedVirtualHostMessageSources"));
    assertModelVersionUpgraded(records);
}

